<map version="1.0.1"><node CREATED="1747229380730" ID="ID_root" MODIFIED="1747229380730" TEXT="Shell命令"><node CREATED="1747229380730" ID="ID_102492a0bbc2d925" POSITION="right" MODIFIED="1747229380730" TEXT="概述"><node CREATED="1747229380730" ID="ID_f2846011df78cea4" MODIFIED="1747229380730" TEXT="在Linux部分，我们要学习命令。&amp;nbsp;也就是用命令代替之前的可视化界面。&amp;nbsp;"></node><node CREATED="1747229380730" ID="ID_6ffac9b1fd359811" MODIFIED="1747229380730" TEXT="要尽快熟悉一下指令。&amp;nbsp;"></node><node CREATED="1747229380730" ID="ID_62792b183a27e0ff" MODIFIED="1747229380730" TEXT="软件"><node CREATED="1747229380730" ID="ID_713e7c374c77897b" MODIFIED="1747229380730" TEXT="VMware/ubuntu/xshell/vimplus"></node></node><node CREATED="1747229380730" ID="ID_9b861129ddd60dd0" MODIFIED="1747229380730" TEXT="Linux的注意事项"><node CREATED="1747229380730" ID="ID_5358eb67e2509384" MODIFIED="1747229380730" TEXT="1.输密码的时候看不到密码。甚至连 *都没有回显"></node><node CREATED="1747229380730" ID="ID_1ba6325d9c3056ea" MODIFIED="1747229380730" TEXT="2.没有消息就是最好的消息。&amp;nbsp;如果输入一条命令，没有得到反馈，说明它成功了。&amp;nbsp;&amp;lt;br&amp;gt;如果有反馈，可能是出错了，看一下反馈信息"></node><node CREATED="1747229380730" ID="ID_9cc70042b5e86739" MODIFIED="1747229380730" TEXT="3.&amp;nbsp;在shell里面。&amp;nbsp;可以使用&amp;nbsp; tab&amp;nbsp;进行补全。&amp;lt;br&amp;gt;会对一些没有争议的路径名补全"></node><node CREATED="1747229380730" ID="ID_4627976a6e1ba3e1" MODIFIED="1747229380730" TEXT="4.上下键可以上一次输入的命令。&amp;nbsp;"><node CREATED="1747229380730" ID="ID_2609208f938fab81" MODIFIED="1747229380730" TEXT="刚开始多练习一下命令。&amp;nbsp;"></node><node CREATED="1747229380730" ID="ID_9c6f29f7c2504346" MODIFIED="1747229380730" TEXT="ctrl + r&amp;nbsp;是搜索命令，之前输入过的命令，可以搜索。&amp;nbsp;"></node></node></node></node><node CREATED="1747229380730" ID="ID_1728361c3bc46624" POSITION="right" MODIFIED="1747229380730" TEXT="man命令"><node CREATED="1747229380730" ID="ID_2304f02f7314be13" MODIFIED="1747229380730" TEXT="帮助命令，我们可以用它看命令。看系统调用（Linux内核对外提供的函数，用来完成特定功能的）。也可以看库函数&amp;lt;br&amp;gt;"></node><node CREATED="1747229380730" ID="ID_89071285fb6fbb54" MODIFIED="1747229380730" TEXT="一定要知道卷1代表的是命令；&amp;nbsp;卷2代表的是系统调用；&amp;nbsp;卷3代表库函数"></node><node CREATED="1747229380730" ID="ID_0c567174c7b89c68" MODIFIED="1747229380730" TEXT="man命令关注信息"><node CREATED="1747229380730" ID="ID_aea39a0162301b5d" MODIFIED="1747229380730" TEXT="首先是Name，主要是一个极简概括"></node><node CREATED="1747229380730" ID="ID_ed9e61164f9bccdc" MODIFIED="1747229380730" TEXT="SYNOPSIS。头文件，&amp;nbsp;函数声明"></node><node CREATED="1747229380730" ID="ID_46db9acc23c3a4ab" MODIFIED="1747229380730" TEXT="DESCRIPTION：&amp;nbsp;详细描述&amp;lt;br&amp;gt;"></node><node CREATED="1747229380730" ID="ID_41bcdde9dc6c2547" MODIFIED="1747229380730" TEXT="RETURN&amp;nbsp;值：&amp;nbsp;描述自己的返回值是什么含义"></node></node><node CREATED="1747229380730" ID="ID_96e3bc8b6acb8b5d" MODIFIED="1747229380730" TEXT="一定要会用，这个是后续学函数的基础。&amp;nbsp;"></node></node><node CREATED="1747229380730" ID="ID_c370feb863b081e0" POSITION="right" MODIFIED="1747229380730" TEXT="用户子系统"><node CREATED="1747229380730" ID="ID_b9ff9a1ec17a59fd" MODIFIED="1747229380730" TEXT="Linux系统可以同时有多个用户，登录上一台Linux。&amp;nbsp;&amp;lt;br&amp;gt;Linux是一个多用户的系统。&amp;nbsp;"><node CREATED="1747229380730" ID="ID_08c89f93480e1396" MODIFIED="1747229380730" TEXT="Linux的权限是比较严的。"></node></node><node CREATED="1747229380730" ID="ID_da0cb2c0b4802fe2" MODIFIED="1747229380730" TEXT="用户的分类"><node CREATED="1747229380730" ID="ID_07eeac60fef13b0d" MODIFIED="1747229380730" TEXT="root用户：&amp;nbsp;最高权限的用户。&amp;nbsp;"></node><node CREATED="1747229380730" ID="ID_368b38f953bddcdd" MODIFIED="1747229380730" TEXT="普通用户：平常用的时候，用普通用户。&amp;nbsp;"><node CREATED="1747229380730" ID="ID_4f61ca53c9de49d5" MODIFIED="1747229380730" TEXT="建议学习的时候，使用普通用户。&amp;nbsp;如果遇到了权限问题，再解决权限问题。&amp;nbsp;&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229380730" ID="ID_82f57e9a9f4fd6c5" MODIFIED="1747229380730" TEXT="sudo用户。就是可以让自己执行命令的时候，假装自己是管理员。&amp;nbsp;"></node></node><node CREATED="1747229380730" ID="ID_2792b6b447f68761" MODIFIED="1747229380730" TEXT="家目录强调一下"><node CREATED="1747229380730" ID="ID_268150a67f4b9aaf" MODIFIED="1747229380730" TEXT="家目录就是一个目录。你进到这个目录之后，权限会非常的友好。&amp;nbsp;&amp;lt;br&amp;gt;家目录是分用户的，你只能回自己家。&amp;nbsp;"></node><node CREATED="1747229380730" ID="ID_ba5b30d086e2afe6" MODIFIED="1747229380730" TEXT="对于root用户。它的家目录就是 /root"></node><node CREATED="1747229380730" ID="ID_b23a31c56091b222" MODIFIED="1747229380730" TEXT="对于非root用户。家目录就是 /home/{username}&amp;lt;br&amp;gt;对于zhou用户，&amp;nbsp;家目录就是 /home/zhou"><node CREATED="1747229380730" ID="ID_d5512a595d28a6ac" MODIFIED="1747229380730" TEXT="家目录不是 /home"></node></node></node><node CREATED="1747229380730" ID="ID_5950cf3c0265663c" MODIFIED="1747229380730" TEXT="这个命令自己练习一下，&amp;nbsp;但是工作时候用的很少。&amp;nbsp;&amp;lt;br&amp;gt;但是自己学习的时候有时候会用到。"><node CREATED="1747229380730" ID="ID_79cbcae077c2175c" MODIFIED="1747229380730" TEXT="对于用户的增删改查"></node><node CREATED="1747229380730" ID="ID_2f491be794d7137c" MODIFIED="1747229380730" TEXT="添加用户，查看用户，删除用户，设置密码，切换用户&amp;lt;br&amp;gt;自己练一下。&amp;nbsp;&amp;lt;br&amp;gt;如果在工作中，碰到了这种实际的需求，查一下命令"></node></node></node><node CREATED="1747229380730" ID="ID_0039fd8f73fd202b" POSITION="right" MODIFIED="1747229380730" TEXT="Linux文件系统"><node CREATED="1747229380730" ID="ID_7b8d9d4664b4934c" MODIFIED="1747229380730" TEXT="组织方式不一样"><node CREATED="1747229380730" ID="ID_da6d25445bcc91de" MODIFIED="1747229380730" TEXT="1.windows的路径，是一个森林结构。 C&amp;nbsp; D E&amp;lt;br&amp;gt;Linux里面，是树状的。&amp;nbsp; &amp;nbsp; /"></node><node CREATED="1747229380730" ID="ID_ec9c31434bc539fe" MODIFIED="1747229380730" TEXT="2.软件组织方式不一样"><node CREATED="1747229380730" ID="ID_039f751ec67995e5" MODIFIED="1747229380730" TEXT="在windows中，基本是以文件夹的形式组织一个软件的。&amp;nbsp;&amp;lt;br&amp;gt;比如，装一个qq，&amp;nbsp;将这个qq的所有文件全部放在一个大文件夹中。"></node><node CREATED="1747229380730" ID="ID_4861df6b4aa2d2a2" MODIFIED="1747229380730" TEXT="在Linux里面，是按照类别来的。&amp;nbsp;比如要装qq，&amp;nbsp;会将启动的命令放在一个集中的文件夹中，&amp;lt;br&amp;gt;配置会放在另外的一个文件夹中；如果要装wps，类似"></node><node CREATED="1747229380730" ID="ID_0e61b4971ea802b9" MODIFIED="1747229380730" TEXT="启动命令、配置文件、库"></node></node><node CREATED="1747229380730" ID="ID_70a77be4b43c6ede" MODIFIED="1747229380730" TEXT="一些比较重要的"><node CREATED="1747229380730" ID="ID_27c73715ee73301e" MODIFIED="1747229380730" TEXT="/bin：&amp;nbsp;存储可执行程序和脚本的&amp;lt;br&amp;gt;/usr/bin"></node><node CREATED="1747229380730" ID="ID_3d94c1e776c7ba7c" MODIFIED="1747229380730" TEXT="/etc:&amp;nbsp;配置文件的"></node><node CREATED="1747229380730" ID="ID_a9aea165a55bfb4a" MODIFIED="1747229380730" TEXT="/lib：系统库文件"></node><node CREATED="1747229380730" ID="ID_8b3986b7c40f4e22" MODIFIED="1747229380730" TEXT="/root"></node><node CREATED="1747229380730" ID="ID_27603c37a7748a99" MODIFIED="1747229380730" TEXT="/home/{username}"></node></node></node><node CREATED="1747229380730" ID="ID_2184781cd75b842d" MODIFIED="1747229380730" TEXT="虚拟文件系统"><node CREATED="1747229380730" ID="ID_ee3eeb92d80120ab" MODIFIED="1747229380730" TEXT="软盘、机械盘、固态盘。真实文件组织是否一样？不一样。&amp;nbsp;&amp;nbsp;"></node><node CREATED="1747229380730" ID="ID_3eb79a7b1073f53b" MODIFIED="1747229380730" TEXT="虚拟文件系统：&amp;nbsp;就是一套虚拟的文件系统。使用这个虚拟文件系统，可以映射到不同的盘上。&amp;nbsp;&amp;lt;br&amp;gt;/home/zhou/2.txt。&amp;nbsp;对于用户来说，不需要关心是什么盘。&amp;nbsp;"></node><node CREATED="1747229380730" ID="ID_708e690205a7e7e8" MODIFIED="1747229380730" TEXT="树就是我们所说的虚拟文件系统。使用它可以帮助我们统一，我们也不需要关心真实的物理存储方式。&amp;nbsp;"></node><node CREATED="1747229380730" ID="ID_374fa443f368bad1" MODIFIED="1747229380730" TEXT="虚拟文件系统，就是一个逻辑关系，维护这个逻辑关系，这个逻辑关系最终会有一个对应。&amp;lt;br&amp;gt;虚拟文件系统，最终会真实对应到物理文件系统上去。"></node></node><node CREATED="1747229380730" ID="ID_2d4645a3362149bd" MODIFIED="1747229380730" TEXT="虚拟文件系统到物理文件系统之间其实存在映射"><node CREATED="1747229380730" ID="ID_9c767fd1fd258f5b" MODIFIED="1747229380730" TEXT="这个叫做硬链接"></node><node CREATED="1747229380730" ID="ID_710697c934c9de0e" MODIFIED="1747229380730" TEXT="硬链接数也需要理解"></node><node CREATED="1747229380730" ID="ID_c4c26ac3e0f4a889" MODIFIED="1747229380730" TEXT="硬链接的使用：&amp;nbsp;创建一个 1.txt文件。里面写一些内容&amp;lt;br&amp;gt;创建一个硬链接，"></node><node CREATED="1747229380730" ID="ID_96abf264da6f06b6" MODIFIED="1747229380730" TEXT="硬链接数的计算"><node CREATED="1747229380730" ID="ID_96a3a14a9db114c3" MODIFIED="1747229380730" TEXT="对于文件，比较容易理解。&amp;nbsp;创建一个文件，硬链接数就是1"></node><node CREATED="1747229380730" ID="ID_5001745ec58d049b" MODIFIED="1747229380730" TEXT="对于文件夹，创建一个文件夹，硬链接数是多少"><node CREATED="1747229380730" ID="ID_224bccf05fdf0bef" MODIFIED="1747229380730" TEXT="背景： 对于新建任意一个文件夹，里面自带两个文件夹。&amp;nbsp;&amp;lt;br&amp;gt;.&amp;nbsp; ..&amp;lt;br&amp;gt;.对应的是当前文件夹； ..对应的是上一级文件夹"></node><node CREATED="1747229380730" ID="ID_af7ffe9ab940b0a9" MODIFIED="1747229380730" TEXT="创建一个test1文件夹。 test1自己是指向自己的。 （硬链接数+1）&amp;lt;br&amp;gt;里面，自带 .&amp;nbsp; &amp;nbsp;..&amp;nbsp; &amp;nbsp;; .指向当前目录（硬链接数 +1）"></node><node CREATED="1747229380730" ID="ID_e203e1debc7bf6f7" MODIFIED="1747229380730" TEXT="如果在test1里面，再建一个test2。&amp;nbsp;这时候。 test2&amp;lt;br&amp;gt;test1的硬链接数，会变成3。&amp;nbsp;原因是&amp;nbsp; test2里面有个 ..。&amp;nbsp;指向test1"></node></node></node></node><node CREATED="1747229380730" ID="ID_848d55ac4f23b7ff" MODIFIED="1747229380730" TEXT="真实存储的物理文件系统上，还有一个叫做inode的结点，用以存储一些信息，比如文件的权限、大小、时间戳&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229380730" ID="ID_424db45ee68ed179" POSITION="right" MODIFIED="1747229380730" TEXT="目录相关命令"><node CREATED="1747229380730" ID="ID_87e05bc5db8fb4ee" MODIFIED="1747229380730" TEXT="之前我们在windows下，都是可视化的。但是现在Linux下都是命令行，所以我们要学会用命令行看目录。&amp;lt;br&amp;gt;创目录、删目录"></node><node CREATED="1747229380730" ID="ID_5eb92b0e3f712ee0" MODIFIED="1747229380730" TEXT="查看当前目录"><node CREATED="1747229380730" ID="ID_6581c049848c56ae" MODIFIED="1747229380730" TEXT="pwd"></node></node><node CREATED="1747229380730" ID="ID_9fca74732c63bc5e" MODIFIED="1747229380730" TEXT="改变当前目录"><node CREATED="1747229380730" ID="ID_6b2e8e211ed4ea9a" MODIFIED="1747229380730" TEXT="cd&amp;nbsp;进入某个目录"></node><node CREATED="1747229380730" ID="ID_affa8c3df68dfa6f" MODIFIED="1747229380730" TEXT="cd ~"><node CREATED="1747229380730" ID="ID_cd88be9d76cb1fb4" MODIFIED="1747229380730" TEXT="回家目录。回这个用户对应的家目录"></node></node><node CREATED="1747229380730" ID="ID_c43ca9140205697e" MODIFIED="1747229380730" TEXT="cd&amp;nbsp;相对路径/绝对路径"></node><node CREATED="1747229380730" ID="ID_1b372e6948d53201" MODIFIED="1747229380730" TEXT="..用的比较多"></node><node CREATED="1747229380730" ID="ID_739fbefbdeb41b4f" MODIFIED="1747229380730" TEXT="~&amp;nbsp;代表的是家目录。&amp;nbsp;用的很多。&amp;nbsp;"></node><node CREATED="1747229380730" ID="ID_50c492afeb0e84ff" MODIFIED="1747229380730" TEXT="可以写相对路径，也可以写绝对路径&amp;nbsp;&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229380730" ID="ID_bd511c039ee78966" MODIFIED="1747229380730" TEXT="创建目录"><node CREATED="1747229380730" ID="ID_f46bbf833b66be30" MODIFIED="1747229380730" TEXT="mkdir创建目录。&amp;nbsp;"></node><node CREATED="1747229380730" ID="ID_ac9dd25b700f8dab" MODIFIED="1747229380730" TEXT="只能创建单级目录。&amp;nbsp;如果要创建多级目录。 -p"></node></node><node CREATED="1747229380730" ID="ID_d7debc1197763c40" MODIFIED="1747229380730" TEXT="查看目录"><node CREATED="1747229380730" ID="ID_fa0defbfaad6363c" MODIFIED="1747229380730" TEXT="ls：&amp;nbsp;重要"></node><node CREATED="1747229380730" ID="ID_98fbf42f8becc42d" MODIFIED="1747229380730" TEXT="ls&amp;nbsp;单写的时候，显示的是当前目录有哪些内容。&amp;lt;br&amp;gt;ls&amp;nbsp;后可以跟相对路径，也可以跟绝对路径"></node><node CREATED="1747229380730" ID="ID_4363cc16f9c00505" MODIFIED="1747229380730" TEXT="ls&amp;nbsp;目录：就是显示该目录下的内容"></node><node CREATED="1747229380730" ID="ID_84f9ac7d75015394" MODIFIED="1747229380730" TEXT="-a选项"><node CREATED="1747229380730" ID="ID_ab7a0e965ce3f71a" MODIFIED="1747229380730" TEXT="表示显示所有的文件，包括隐藏的。&amp;nbsp;在Linux里面， .开头也是隐藏的。&amp;nbsp;&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229380730" ID="ID_487c0086e34a563d" MODIFIED="1747229380730" TEXT="-l选项。&amp;nbsp;非常重要&amp;lt;br&amp;gt;要知道显示的内容的含义"><node CREATED="1747229380730" ID="ID_35bf1296ad305b8a" MODIFIED="1747229380730" TEXT="第一列表示它的类型。&amp;nbsp;是个文件，还是文件夹。&amp;nbsp;&amp;lt;br&amp;gt;-表示是文件； d表示是目录"></node><node CREATED="1747229380730" ID="ID_5d3849b5fde14abb" MODIFIED="1747229380730" TEXT="后面9个字符，表示的是权限。&amp;nbsp;&amp;lt;br&amp;gt;rwx:&amp;nbsp;表示读权限，写权限，执行权限&amp;lt;br&amp;gt;"><node CREATED="1747229380730" ID="ID_67197e7d415d33bb" MODIFIED="1747229380730" TEXT="其实表示的是给三类人的权限。&amp;nbsp;第一个rwx，表示的是给自己的权限。&amp;nbsp;"></node><node CREATED="1747229380730" ID="ID_a772c29ae561a20a" MODIFIED="1747229380730" TEXT="第一个表示的是自己的权限。&amp;nbsp;&amp;lt;br&amp;gt;第二个表示的是给同组人的&amp;lt;br&amp;gt;第三个表示的是给其他人的权限"></node></node><node CREATED="1747229380730" ID="ID_9d2739253bc91757" MODIFIED="1747229380730" TEXT="硬链接数"></node><node CREATED="1747229380730" ID="ID_eb7f57fbb6560e4a" MODIFIED="1747229380730" TEXT="文件的所有者&amp;lt;br&amp;gt;文件的所有组"></node><node CREATED="1747229380730" ID="ID_1b95a1fc19156fcd" MODIFIED="1747229380730" TEXT="文件的大小"><node CREATED="1747229380730" ID="ID_de20ed764746cf9c" MODIFIED="1747229380730" TEXT="h human&amp;nbsp;以人类更友好的方式显示。会换单位&amp;lt;br&amp;gt;ls -alh"></node></node><node CREATED="1747229380730" ID="ID_48362220b39b5c46" MODIFIED="1747229380730" TEXT="-l选项中的所有内容都要记住。&amp;nbsp;"></node></node><node CREATED="1747229380730" ID="ID_9731234d0125af9c" MODIFIED="1747229380730" TEXT="查看这里用的最多的： &amp;lt;br&amp;gt;ll&amp;lt;br&amp;gt;ls -al"></node></node><node CREATED="1747229380730" ID="ID_12509950c78e9428" MODIFIED="1747229380730" TEXT="复制文件"><node CREATED="1747229380730" ID="ID_b84f61bfc0d2702c" MODIFIED="1747229380730" TEXT="cp test1.txt&amp;nbsp; test2.txt&amp;nbsp;"></node><node CREATED="1747229380730" ID="ID_f1c80a44ff183e66" MODIFIED="1747229380730" TEXT="cp test1.txt dir"></node></node><node CREATED="1747229380730" ID="ID_bbf3c0751baccb59" MODIFIED="1747229380730" TEXT="移动文件"><node CREATED="1747229380730" ID="ID_a1fc31302977faad" MODIFIED="1747229380730" TEXT="mv&amp;nbsp; test1.txt test2.txt&amp;lt;br&amp;gt;mv test1.txt dir"></node></node><node CREATED="1747229380730" ID="ID_c67aff134798446a" MODIFIED="1747229380730" TEXT="删除文件"><node CREATED="17472293